export const isFakeListing = (id?: string): boolean => (id ? FAKE_LISTING_IDS.has(id) : false);

export const formatCarpetArea = (area: number | string, listingId?: string) => {
  const num = Number(area);
  if (!num || isNaN(num)) return { display: 'N/A', unit: 'sqft', isSqm: false, convertedSqft: 0 };
  const isSqm = listingId?.startsWith('MAG-') || false;
  if (isSqm) {
    const inSqft = Math.round(num * 10.7639);
    return {
      display: `${num} sqm (~${inSqft.toLocaleString()} sqft)`,
      unit: 'sqm',
      isSqm: true,
      convertedSqft: inSqft
    };
  }
  return {
    display: `${num.toLocaleString()} sqft`,
    unit: 'sqft',
    isSqm: false,
    convertedSqft: num
  };
};

